	out.Reset()
	if err := runTrust(cmd, true); err != nil {
		t.Fatalf("runTrust --revoke: %v", err)
	}
	if !strings.Contains(out.String(), "Revoked trust for github.com/acme/widgets") {
		t.Fatalf("revoke output = %q", out.String())
