			slog.String("error", err.Error()))
		return nil
	}
	if !repoConfigured {
		MaybeEnsureGlobalSetup(ctx)
		return nil
	}
	// Hook context: discard ref-bootstrap notices — a ✓ line on stderr here
	// would leak into the agent's hook output.
	return ensureSetup(ctx, io.Discard)
}

